diff --git a/src/domain/batches.js b/src/domain/batches.js
index ee14fde..dcedd52 100644
--- a/src/domain/batches.js
+++ b/src/domain/batches.js
@@ -18,9 +18,19 @@ export function getBatch(store, id) {
   return batch;
 }

-// The order in which an item's batches are used up.
+// The order in which an item's batches are used up (FEFO, docs/DATA.md):
+// earliest expiry first, no expiry last, then received first, then lower id.
 function consumptionOrder(batches) {
-  return [...batches].sort((a, b) => b.receivedOn.localeCompare(a.receivedOn));
+  return [...batches].sort((a, b) => {
+    const ea = a.expires || null;
+    const eb = b.expires || null;
+    if (ea !== eb) {
+      if (!ea) return 1;
+      if (!eb) return -1;
+      return ea.localeCompare(eb);
+    }
+    return a.receivedOn.localeCompare(b.receivedOn) || a.id - b.id;
+  });
 }

